  struct aic_pwm_arg *arg = NULL;

  if (hal_pwm_ch_check(ch) < 0)
    return -EINVAL;

  arg = &g_pwm_args[ch];

  if (!arg->available) {
    hal_log_err("ch%d is unavailable\n", ch);
    return -EINVAL;
  }

  if (cnt > PWM_TBPRD_MAX) {
    hal_log_err("ch%d period %d is too big\n", ch, cnt);
