/****************************************************************************
 * apps/velacare/velacare_main.c — VelaCare 主进程入口
 *
 * 队伍 438 (baimi) · 2026 openvela AI 硬件开发者大赛
 *
 * 职责:
 *   1. 初始化 4 级状态机
 *   2. 装载 4 个 Skill 到 ai_agent
 *   3. 注册 cron 定时任务
 *   4. 启动 LVGL 显示线程
 *   5. 进入主循环, 1Hz 轮询传感器 + 评估状态机
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <stdbool.h>
#include <stdint.h>
#include <syslog.h>
